import "./Admin.css";
import { useEffect, useState } from "react";

function Admin() {
  // ======= AUTH STATES =======
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [token, setToken] = useState(null);

  // ======= INQUIRIES STATES =======
  const [inquiries, setInquiries] = useState([]);
  const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const inquiriesPerPage = 5;

  // ======= SERVICES STATES =======
  const [services, setServices] = useState([]);
  const [serviceName, setServiceName] = useState("");
  const [documents, setDocuments] = useState("");
  const [price, setPrice] = useState("");
  const [duration, setDuration] = useState("");
  const [description, setDescription] = useState("");
  const [imageURL, setImageURL] = useState("");

  // ======= SLIDER STATES =======
  const [selectedFile, setSelectedFile] = useState(null);
  const [images, setImages] = useState([]);

  // ======= SECTION STATE =======
  const [activeSection, setActiveSection] = useState(null); // "inquiries" | "services" | "slider" | null

  // ======= LOGIN FUNCTION =======
  const login = async () => {
    if (!username || !password) return alert("Enter username and password");

    const formData = new FormData();
    formData.append("username", username);
    formData.append("password", password);

    try {
      const res = await fetch("http://127.0.0.1:8000/login", {
        method: "POST",
        body: formData,
      });
      const data = await res.json();
      if (res.ok) {
        alert("Login successful!");
        setToken(data.access_token); // Save JWT token
      } else {
        alert(data.detail);
      }
    } catch (err) {
      console.error("Login error:", err);
    }
  };

  // ======= FETCH INQUIRIES =======
  const fetchInquiries = async () => {
    try {
      const response = await fetch("http://127.0.0.1:8000/inquiries", {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      setInquiries(data);
    } catch (error) {
      console.error("Error fetching inquiries:", error);
    }
  };

  const deleteInquiry = async (id) => {
    try {
      const response = await fetch(`http://127.0.0.1:8000/inquiry/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (response.ok) {
        alert("Inquiry deleted successfully!");
        fetchInquiries();
      } else {
        const err = await response.json();
        alert(err.detail);
      }
    } catch (error) {
      console.error("Error deleting inquiry:", error);
    }
  };

  // ======= FETCH SERVICES =======
  const fetchServices = async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/services", {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setServices(data);
    } catch (err) {
      console.error("Error fetching services:", err);
    }
  };

  const addService = async () => {
    if (!serviceName || !documents || !price || !duration || !description) {
      alert("Please fill all fields");
      return;
    }
    try {
      const res = await fetch("http://127.0.0.1:8000/service", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          serviceName,
          documents,
          price,
          duration,
          description,
          imageURL,
        }),
      });
      if (res.ok) {
        alert("Service added successfully!");
        fetchServices();
        setServiceName("");
        setDocuments("");
        setPrice("");
        setDuration("");
        setDescription("");
        setImageURL("");
      }
    } catch (err) {
      console.error("Error adding service:", err);
    }
  };

  const deleteService = async (id) => {
    try {
      const res = await fetch(`http://127.0.0.1:8000/service/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        alert("Service deleted successfully!");
        fetchServices();
      }
    } catch (err) {
      console.error("Error deleting service:", err);
    }
  };

  // ======= SLIDER IMAGES =======
  const fetchImages = async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/images", {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setImages(data.images || []);
    } catch (err) {
      console.error("Error fetching images:", err);
    }
  };

  const handleUpload = async () => {
    if (!selectedFile) return alert("Select a file first!");

    const formData = new FormData();
    formData.append("file", selectedFile);

    await fetch("http://127.0.0.1:8000/upload-image", {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: formData,
    });

    alert("Image uploaded successfully!");
    fetchImages();
  };

  const handleDeleteImage = async (imageName) => {
    const confirmDelete = window.confirm("Are you sure to delete this image?");
    if (!confirmDelete) return;

    await fetch(`http://127.0.0.1:8000/delete-image/${imageName}`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
    });

    alert("Image deleted successfully!");
    fetchImages();
  };

  // ======= PAGINATION =======
  const indexOfLastInquiry = currentPage * inquiriesPerPage;
  const indexOfFirstInquiry = indexOfLastInquiry - inquiriesPerPage;

  const filteredInquiries = inquiries
    .filter(
      (inq) =>
        inq.name.toLowerCase().includes(search.toLowerCase()) ||
        inq.mobile.includes(search)
    )
    .sort((a, b) => new Date(b.date) - new Date(a.date));

  const currentInquiries = filteredInquiries.slice(
    indexOfFirstInquiry,
    indexOfLastInquiry
  );

  const totalPages = Math.ceil(filteredInquiries.length / inquiriesPerPage);

  const handleNext = () => {
    if (currentPage < totalPages) setCurrentPage(currentPage + 1);
  };
  const handlePrev = () => {
    if (currentPage > 1) setCurrentPage(currentPage - 1);
  };

  // ======= USE EFFECT =======
  useEffect(() => {
    if (!token) return;
    if (activeSection === "inquiries") fetchInquiries();
    if (activeSection === "services") fetchServices();
    if (activeSection === "slider") fetchImages();
  }, [activeSection, token]);

  // ======= RENDER LOGIN IF NO TOKEN =======
  if (!token) {
    return (
      <div className="login-container">
        <h2>Admin Login</h2>
        <input
          type="text"
          placeholder="Username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <button onClick={login}>Login</button>
      </div>
    );
  }

  // ======= ADMIN DASHBOARD =======
  return (
    <div className="admin-container">
      <h1>Admin Dashboard</h1>

      {!activeSection && (
        <div className="admin-menu">
          <button onClick={() => setActiveSection("inquiries")}>
            📋 Manage Inquiries
          </button>
          <button onClick={() => setActiveSection("services")}>
            🛠 Manage Services
          </button>
          <button onClick={() => setActiveSection("slider")}>
            🖼 Manage Slider Images
          </button>
        </div>
      )}

      {/* ======= INQUIRIES SECTION ======= */}
      {activeSection === "inquiries" && (
        <div className="inquiries-section">
          <h2>Inquiries</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>
          <input
            type="text"
            placeholder="Search by name or mobile..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          {inquiries.length === 0 ? (
            <p>No inquiries found.</p>
          ) : (
            <>
              <table border="1" cellPadding="10">
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Mobile</th>
                    <th>Message</th>
                    <th>Date</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {currentInquiries.map((inq) => (
                    <tr key={inq._id}>
                      <td>{inq.name}</td>
                      <td>{inq.email}</td>
                      <td>{inq.mobile}</td>
                      <td>{inq.message}</td>
                      <td>{new Date(inq.date).toLocaleString()}</td>
                      <td>
                        <button onClick={() => deleteInquiry(inq._id)}>
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div>
                <button onClick={handlePrev} disabled={currentPage === 1}>
                  Previous
                </button>
                <button
                  onClick={handleNext}
                  disabled={currentPage === totalPages}
                >
                  Next
                </button>
              </div>
            </>
          )}
        </div>
      )}

      {/* ======= SERVICES SECTION ======= */}
      {activeSection === "services" && (
        <div className="services-section">
          <h2>Manage Services</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>

          <div>
            <input
              type="text"
              placeholder="Service Name"
              value={serviceName}
              onChange={(e) => setServiceName(e.target.value)}
            />
            <input
              type="text"
              placeholder="Documents Required"
              value={documents}
              onChange={(e) => setDocuments(e.target.value)}
            />
            <input
              type="text"
              placeholder="Price"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
            />
            <input
              type="text"
              placeholder="Duration"
              value={duration}
              onChange={(e) => setDuration(e.target.value)}
            />
            <input
              type="text"
              placeholder="Description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
            <input
              type="text"
              placeholder="Image URL"
              value={imageURL}
              onChange={(e) => setImageURL(e.target.value)}
            />
            <button onClick={addService}>Add Service</button>
          </div>

          {services.length > 0 && (
            <table border="1" cellPadding="10">
              <thead>
                <tr>
                  <th>Service Name</th>
                  <th>Documents</th>
                  <th>Price</th>
                  <th>Duration</th>
                  <th>Description</th>
                  <th>Image</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {services.map((s) => (
                  <tr key={s._id}>
                    <td>{s.serviceName}</td>
                    <td>{s.documents}</td>
                    <td>{s.price}</td>
                    <td>{s.duration}</td>
                    <td>{s.description}</td>
                    <td>
                      {s.imageURL && (
                        <img
                          src={s.imageURL}
                          alt={s.serviceName}
                          width="50"
                        />
                      )}
                    </td>
                    <td>
                      <button onClick={() => deleteService(s._id)}>
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {/* ======= SLIDER SECTION ======= */}
      {activeSection === "slider" && (
        <div className="slider-section">
          <h2>Manage Slider Images</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>

          <div style={{ marginBottom: "15px" }}>
            <input
              type="file"
              accept="image/*"
              onChange={(e) => setSelectedFile(e.target.files[0])}
            />
            <button onClick={handleUpload}>Upload</button>
          </div>

          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
            {images.map((url, index) => {
              const fileName = url.split("/").pop();
              return (
                <div key={index} style={{ position: "relative" }}>
                  <img
                    src={url}
                    alt={`slide-${index}`}
                    width="150"
                    style={{ borderRadius: "8px", border: "1px solid #ccc" }}
                  />
                  <button
                    onClick={() => handleDeleteImage(fileName)}
                    style={{
                      position: "absolute",
                      top: "5px",
                      right: "5px",
                      background: "red",
                      color: "white",
                      border: "none",
                      padding: "4px 6px",
                      cursor: "pointer",
                      borderRadius: "4px",
                    }}
                  >
                    X
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export default Admin;
